#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define W 800
#define H 600

/* scene */
static const float CX=0.0f, CY=-0.5f, CZ=-5.0f, R=1.0f; /* sphere */
static const float PY=-1.5f;                             /* plane y */
static float Lx,Ly,Lz;                                   /* light dir */

static int sphere_hit(float ox,float oy,float oz,float dx,float dy,float dz,
                      float *pt,float *hx,float *hy,float *hz,
                      float *nx,float *ny,float *nz){
    float ocx=ox-CX, ocy=oy-CY, ocz=oz-CZ;
    float a=((dx*dx)+(dy*dy))+(dz*dz);
    float b=2.0f*(((ocx*dx)+(ocy*dy))+(ocz*dz));
    float c=(((ocy*ocy)+(ocx*ocx))+(ocz*ocz))-R*R;
    float disc=b*b-(4.0f*a)*c;
    if(disc<0.0f) return 0;
    double sq=sqrt((double)disc);
    float t=(float)(((double)(-b)-sq)/(double)(a+a));
    if(!(0.001f<=t)){
        t=(float)(((double)(-b)+sq)/(double)(a+a));
        if(0.001f>t) return 0;
    }
    float px=(dx*t)+ox, py=(dy*t)+oy, pz=(dz*t)+oz;
    float ax=px-CX, ay=py-CY, az=pz-CZ;
    float nl=sqrtf(((ax*ax)+(ay*ay))+(az*az));
    *pt=t; *hx=px; *hy=py; *hz=pz;
    *nx=ax/nl; *ny=ay/nl; *nz=az/nl;
    return 1;
}

static int in_shadow(float ox,float oy,float oz){
    float t,hx,hy,hz,nx,ny,nz;
    return sphere_hit(ox,oy,oz,Lx,Ly,Lz,&t,&hx,&hy,&hz,&nx,&ny,&nz);
}

static void shade(float hx,float hy,float hz,float nx,float ny,float nz,
                  float br,float bg,float bb,float *r,float *g,float *b){
    float dot=((nx*Lx)+(ny*Ly))+(nz*Lz);
    float m=(float)fmax(0.0,(double)dot);
    float factor;
    if(in_shadow(hx,hy,hz)) factor=0.2f;
    else factor=(m*0.8f)+0.2f;
    *r=br*factor; *g=bg*factor; *b=bb*factor;
}

static void trace(float ox,float oy,float oz,float dx,float dy,float dz,
                  float *r,float *g,float *b){
    float t,hx,hy,hz,nx,ny,nz;
    if(sphere_hit(ox,oy,oz,dx,dy,dz,&t,&hx,&hy,&hz,&nx,&ny,&nz)){
        shade(hx,hy,hz,nx,ny,nz,1.0f,0.2f,0.2f,r,g,b);
        return;
    }
    if(!(1e-4f>fabsf(dy))){
        float tp=(PY-oy)/dy;
        if(!(0.001f>tp)){
            hx=(dx*tp)+ox; hy=(dy*tp)+oy; hz=(dz*tp)+oz;
            long s=(long)((double)floorf(hx)+(double)floorf(hz));
            float chk=(s&1)?0.4f:0.9f;
            shade(hx,hy,hz,0.0f,1.0f,0.0f,chk,chk,chk,r,g,b);
            return;
        }
    }
    /* sky */
    float ty=0.5f*(dy+1.0f);
    *r=(1.0f-ty)+ty*0.5f;
    *g=(1.0f-ty)+ty*0.7f;
    *b=1.0f;
}

int main(void){
    fprintf(stderr,"Creating high-resolution image: %dx%d\n",W,H);
    fwrite("This will be downsampled with ffmpeg after rendering\n",1,53,stderr);
    /* light = normalize(1,1,-1) */
    {float lx=1.0f,ly=1.0f,lz=-1.0f;
     float ll=sqrtf(((lx*lx)+(ly*ly))+(lz*lz));
     Lx=lx/ll; Ly=ly/ll; Lz=lz/ll;}
    float (*img)[W*3]=malloc((size_t)H*sizeof(*img));
    fwrite("Rendering high-resolution image...\n",1,35,stderr);
    for(int y=0;y<H;y++){
        fprintf(stderr,"\rProgress: %.1f%%",(double)((100.0f*(float)y)/600.0f));
        float py=(2.0f*(1.0f-((float)y/599.0f)))-1.0f;
        for(int x=0;x<W;x++){
            float u=(float)x/799.0f;
            float px=(u*(8.0f/3.0f))-(4.0f/3.0f);
            float dz=-1.0f;
            float len=sqrtf(((px*px)+(py*py))+(dz*dz));
            float dx=px/len, dy=py/len; dz=dz/len;
            float r,g,b;
            trace(0.0f,0.0f,0.0f,dx,dy,dz,&r,&g,&b);
            img[y][x*3]=r; img[y][x*3+1]=g; img[y][x*3+2]=b;
        }
    }
    fwrite("\nRendering complete\n",1,20,stderr);
    FILE *f=fopen("image.ppm","w");
    fprintf(f,"P3\n%d %d\n255\n",W,H);
    for(int y=0;y<H;y++)for(int x=0;x<W;x++){
        int o=x*3; int v[3];
        for(int c=0;c<3;c++){
            double d=(double)img[y][o+c];
            d=fmax(0.0,d); d=fmin(1.0,d);
            v[c]=(int)((float)d*255.98999f);
        }
        fprintf(f,"%d %d %d\n",v[0],v[1],v[2]);
    }
    fclose(f);
    fprintf(stderr,"Wrote image to %s\n","image.ppm");
    fwrite("Done.\n",1,6,stderr);
    free(img);
    return 0;
}

